export type FileState = 'up_to_date' | 'waiting' | 'changed_in_both' | 'folder_not_found' | 'could_not_write';
export type ProjectFile = { path: string; what: string; version: number | null; state: FileState; reason?: string };
export type ProjectFiles = { projectId: string; name: string; folder: string | null; writeFiles: boolean; companyFacts: boolean; state: FileState; needsYou: boolean; writtenAt: string | null; version: number | null; files: ProjectFile[] };
export type FileCompare = { path: string; version: number | null; girruText: string; folderText: string };
export type ProblemKind = 'duplicate_number' | 'unknown_number';
export type ProblemAction = 'new_task' | 'add_task' | 'leave';
export type TaskProblem = { id: string; kind: ProblemKind; projectId: string; projectName: string; file: '.girru/tasks.md'; number: string; titles: string[]; line: number };
export type PlaceSettings = Record<string, { staysLocal: boolean }>;
export const FILE_STATES: readonly FileState[];
export const PROJECT_FILE_PATHS: readonly string[];
export const PROBLEM_KINDS: readonly ProblemKind[];
export const PROBLEM_ACTIONS: readonly ProblemAction[];
export const PLACE_KEYS: readonly string[];
export const PROJECT_FILES_PATH: '/api/memory/project-files';
export const PROJECT_FILES_NEEDS_PATH: '/api/memory/project-files/needs-you';
export const PLACE_SETTINGS_PATH: '/api/memory/place-settings';
export function projectFilesPath(projectId: string): string;
export function projectFilesComparePath(projectId: string, file: string): string;
export function projectFilesActionPath(projectId: string, action: 'rewrite' | 'use-girru' | 'undo'): string;
export function taskProblemPath(id: string): string;
export function placeSettingPath(place: string): string;
export function projectFilesPathOf(path: string): { route: 'list' | 'needs' | 'places' | 'compare' | 'rewrite' | 'use-girru' | 'undo' | 'project' | 'problem' | 'place'; id?: string; file?: string } | null;
export function projectFilesRoute(path: string): boolean;
export function allowedProjectFiles(method: string, path: string, body?: unknown): boolean;
export function projectFilesResponse(path: string, status: number, body: unknown): unknown;
